import apartment from '@/data/apartment.json';

/**
 * Art direction v3 §2: 10 × 7 m apartment, generated by tools/apartment/build-apartment.mjs into
 * src/data/apartment.json (single source of truth for 3D, lidar, grid, minimap and the CI path check).
 * x −5…5 west→east, z −3.5…3.5 north→south, floor y 0, no ceiling.
 */
export const ROOM = { w: apartment.footprint.w, d: apartment.footprint.d, wallH: apartment.wallHeight, wallT: apartment.wallThickness.exterior, wallTi: apartment.wallThickness.interior } as const;
export const CUTAWAY = apartment.cutaway;

export interface Box { name: string; x: number; z: number; w: number; d: number; h: number; yaw: number; kind: 'wall' | 'prop'; shape?: 'box' | 'cyl' | 'cone'; color?: string }
/** Wall: outward normal (exterior) or a ±axis normal (interior: the cutaway picks the camera side). */
export interface Wall extends Box { pStart: number; nx: number; nz: number; exterior: boolean; axis: 'x' | 'z' }

const hw = ROOM.w / 2, hd = ROOM.d / 2;
const near = (a: number, b: number) => Math.abs(a - b) < 1e-6;

/** Walls from apartment.json; exterior ends at the footprint corners extend by t/2 so corners close. */
export const WALLS: Wall[] = apartment.walls.map((w) => {
  const axis: 'x' | 'z' = near(w.from[1], w.to[1]) ? 'x' : 'z';
  const t = w.thickness;
  let a = axis === 'x' ? Math.min(w.from[0], w.to[0]) : Math.min(w.from[1], w.to[1]);
  let b = axis === 'x' ? Math.max(w.from[0], w.to[0]) : Math.max(w.from[1], w.to[1]);
  const lim = axis === 'x' ? hw : hd;
  if (w.exterior) { if (near(a, -lim)) a -= t / 2; if (near(b, lim)) b += t / 2; }
  const mid = (a + b) / 2, len = b - a;
  return {
    name: `wall_${w.id}`, kind: 'wall', yaw: 0, h: w.height, exterior: w.exterior, axis,
    x: axis === 'x' ? mid : w.center[0], z: axis === 'x' ? w.center[1] : mid,
    w: axis === 'x' ? len : t, d: axis === 'x' ? t : len,
    nx: w.normal[0], nz: w.normal[1],
    pStart: 0.08 + ((hd - w.center[1]) / ROOM.d) * 0.1, // south (nearest the start camera) rises first
  };
});
export const DOORWAYS = apartment.doorways;

/** Rooms; id = minimap roomId (0 corridor, 1 living, 2 link, 3 kitchen, 4 bath, 5 bed2, 6 bed1). */
export interface RoomRect { id: number; key: string; label: string; x0: number; x1: number; z0: number; z1: number }
const LABEL: Record<string, string> = { link: 'DINING', bed2: 'STUDY', bed1: 'BEDROOM' };
export const ROOMS: RoomRect[] = apartment.rooms.map((r) => ({ id: r.id, key: r.key, label: LABEL[r.key] ?? r.name.toUpperCase(), x0: r.x[0], x1: r.x[1], z0: r.z[0], z1: r.z[1] }));
export const OUTSIDE = 255;
export function roomAt(x: number, z: number): number {
  for (const r of ROOMS) if (x >= r.x0 && x < r.x1 && z >= r.z0 && z < r.z1) return r.id;
  return OUTSIDE;
}

/** Furniture placements (render) + their lidar/collision footprints (colliders are pre-yaw local w × d). */
export type Placement = (typeof apartment.furniture)[number];
export const FURNITURE: Placement[] = apartment.furniture;
export const ACCENTS = apartment.accents;
export const PROPS: Box[] = FURNITURE.filter((f) => f.collider).map((f) => ({
  name: f.node, kind: 'prop', x: f.position[0], z: f.position[2], w: f.collider!.w, d: f.collider!.d, h: f.collider!.h,
  yaw: (f.yaw * Math.PI) / 180, shape: /plant|coffeetable|stool/.test(f.item) ? 'cyl' : 'box',
}));
export const OBSTACLES: Box[] = [...WALLS, ...PROPS];

/** 2D ray (origin, unit dir) vs yawed box footprint in XZ. Returns distance or Infinity. */
export function rayBox(ox: number, oz: number, dx: number, dz: number, b: Box): number {
  const c = Math.cos(-b.yaw), s = Math.sin(-b.yaw);
  const lx = (ox - b.x) * c - (oz - b.z) * s, lz = (ox - b.x) * s + (oz - b.z) * c;
  const ldx = dx * c - dz * s, ldz = dx * s + dz * c;
  const hx = b.w / 2, hz = b.d / 2;
  let t0 = -Infinity, t1 = Infinity;
  for (const [o, d, h] of [[lx, ldx, hx], [lz, ldz, hz]] as const) {
    if (Math.abs(d) < 1e-9) { if (o < -h || o > h) return Infinity; continue; }
    let a = (-h - o) / d, bb = (h - o) / d;
    if (a > bb) [a, bb] = [bb, a];
    t0 = Math.max(t0, a); t1 = Math.min(t1, bb);
    if (t0 > t1) return Infinity;
  }
  return t1 < 0 ? Infinity : Math.max(0, t0);
}

export function castRay(ox: number, oz: number, ang: number, max = 12, list: Box[] = OBSTACLES) {
  const dx = Math.cos(ang), dz = Math.sin(ang);
  let best = max;
  for (const b of list) { const d = rayBox(ox, oz, dx, dz, b); if (d < best) best = d; }
  // Review #12: clamp to the apartment's inner faces so no ray escapes through a door gap in the shell.
  const hx = ROOM.w / 2 - ROOM.wallT / 2, hz = ROOM.d / 2 - ROOM.wallT / 2;
  if (Math.abs(ox) < hx && Math.abs(oz) < hz) {
    const tx = Math.abs(dx) > 1e-9 ? ((dx > 0 ? hx : -hx) - ox) / dx : Infinity;
    const tz = Math.abs(dz) > 1e-9 ? ((dz > 0 ? hz : -hz) - oz) / dz : Infinity;
    best = Math.min(best, tx, tz);
  }
  return { dist: best, hit: best < max, x: ox + dx * best, z: oz + dz * best };
}
